#!/usr/bin/env bash
# Stop hook: warn if CURRENT.md is stale, the version was not bumped since the
# last handoff snapshot, OR a claimed per-slice status file has invalid
# frontmatter. Non-blocking (always exit 0). Stderr is shown to Claude.
#
# Post-migration model: CURRENT.md is a DERIVED lab-wide index (generated by
# scripts/status.sh) and may carry NO top-level `version:` frontmatter. The
# authoritative per-slice baton lives in status/<slice>.md (see
# .agent/status/README.md). This hook therefore validates the PER-SLICE status
# file(s), not CURRENT.md's frontmatter.
set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

# AGENT_ROOT seam: tests point this at a throwaway fixture .agent; unset = the
# repo's own .agent (resolved from BASH_SOURCE, as before).
AGENT_DIR="${AGENT_ROOT:-$ROOT/.agent}"
current="$AGENT_DIR/handoffs/CURRENT.md"
status_dir="$AGENT_DIR/status"
latest_meta="$AGENT_DIR/handoffs/state/latest/meta.txt"

# Portable mtime: GNU stat → BSD stat → Python fallback.
file_mtime() {
    stat -c %Y "$1" 2>/dev/null \
        || stat -f %m "$1" 2>/dev/null \
        || python3 -c "import os,sys; print(int(os.path.getmtime(sys.argv[1])))" "$1" 2>/dev/null \
        || echo ""
}

# ── Stale-mtime check on CURRENT.md (harmless under the index format) ─────────
if [ -f "$current" ]; then
    now=$(date +%s)
    m=$(file_mtime "$current")
    if [ -z "$m" ]; then
        # Can't read mtime — skip the stale-time check silently.
        age_min=0
    else
        age_min=$(( (now - m) / 60 ))
    fi

    if [ "$age_min" -gt 60 ]; then
        {
            echo "[handoff-check] CURRENT.md was not updated in ${age_min}min."
            echo "Before stopping, update .agent/handoffs/CURRENT.md (or invoke /handoff)"
            echo "so the next agent can resume from files, not chat history."
        } >&2
    fi

    # Detect "agent forgot to bump version since last handoff snapshot".
    # handoff.sh increments the `version` and records `current_version` in
    # state/latest/meta.txt. If they match at Stop time, either /handoff was
    # never called this session OR no real changes were made. Both worth a
    # warning. Post-migration CURRENT.md is a derived index that may have NO
    # top-level `version:` frontmatter; the `[ -n "$fm_version" ]` guard below
    # skips cleanly in that case (no false warning).
    if [ -f "$latest_meta" ]; then
        snap_version=$(awk -F': *' '/^current_version:/ { print $2 }' "$latest_meta" | tr -d '[:space:]')
        fm_version=$(awk '
            /^---$/ { in_fm = !in_fm; next }
            in_fm && /^version:/ { print $2; exit }
        ' "$current" | tr -d '[:space:]')
        if [ -n "${snap_version:-}" ] && [ -n "${fm_version:-}" ] && [ "$snap_version" = "$fm_version" ]; then
            {
                echo "[handoff-check] CURRENT.md version ($fm_version) has not changed since the last snapshot."
                echo "Run /handoff or ./scripts/handoff.sh <agent> to record this session's state."
            } >&2
        fi
    fi
fi

# ── Per-slice frontmatter schema validation ───────────────────────────────────
#
# Target is status/<slice>.md, NOT CURRENT.md. Per-slice schema
# (.agent/status/README.md) required fields:
#   owner_session, owner_agent, version, last_updated, heartbeat,
#   remaining_actions.
# Checks: owner_agent ∈ VALID_AGENTS; remaining_actions is a list;
# last_updated is ISO and ≤7d old; NO unfilled "<...>" placeholder anywhere in
# the frontmatter. (The slice IS the filename now — no active_slice scalar, no
# VALID_SLICES-on-scalar check.)
#
# Which file(s):
#   - ENTERING_SLICE set & non-empty → validate just that slice; on success
#     echo a single proof line naming the file and emit NO violation lines.
#   - ENTERING_SLICE unset → validate EVERY slice with a non-empty
#     owner_session (claimed slices); warn per offending field. If none
#     claimed, do nothing.
#
# stdlib only. PyYAML used for richer type checks when present; otherwise a
# minimal line-based parser (reused below) covers the required-field subset.
validate_slice() {
    # $1 = path to a status/<slice>.md ; prints violation lines to stderr,
    # prints "[handoff-check] validated status/<slice>.md (ok)" to stderr on
    # clean validation. Never changes exit status of the hook.
    python3 - "$1" <<'PY' 2>&1 1>&2 || true
import sys, os, re, datetime

VALID_AGENTS = {"claude", "codex", "cursor", "human"}
MAX_AGE_DAYS = 7
REQUIRED = ["owner_session", "owner_agent", "version", "last_updated",
            "heartbeat", "remaining_actions"]

path = sys.argv[1]
rel = "status/" + os.path.basename(path)

try:
    text = open(path).read()
except OSError as e:
    print(f"[handoff-check] {rel}: cannot read ({e}). frontmatter validation skipped.", file=sys.stderr)
    sys.exit(0)

m = re.match(r'\A---\s*\n(.*?)\n---\s*\n', text, re.DOTALL)
if not m:
    print(f"[handoff-check] {rel} missing yaml frontmatter. Add the per-slice schema block at top.", file=sys.stderr)
    sys.exit(0)
block = m.group(1)

# --- Try PyYAML; if missing, use a stdlib mini-parser ---
try:
    import yaml
    try:
        fm = yaml.safe_load(block) or {}
    except yaml.YAMLError as e:
        print(f"[handoff-check] {rel} frontmatter is invalid YAML: {e}", file=sys.stderr)
        sys.exit(0)
except ImportError:
    # Mini-parser: handles the subset we actually use — scalars, ISO dates,
    # list-of-string blocks ("key:" + "  - item"). Good enough to validate the
    # required fields without PyYAML.
    fm = {}
    cur_list_key = None
    for line in block.splitlines():
        if not line.strip():
            continue
        if cur_list_key and re.match(r'^\s+-\s', line):
            fm[cur_list_key].append(re.sub(r'^\s+-\s+', '', line).strip().strip('"').strip("'"))
            continue
        cur_list_key = None
        mkv = re.match(r'^([A-Za-z_][A-Za-z0-9_-]*):\s*(.*)$', line)
        if not mkv:
            continue
        key, val = mkv.group(1), mkv.group(2).rstrip()
        if val == "":
            fm[key] = []          # may turn into list when items follow
            cur_list_key = key
        elif val in ("~", "null"):
            fm[key] = None
        elif val.lower() in ("true", "false"):
            fm[key] = (val.lower() == "true")
        else:
            v = val.strip().strip('"').strip("'")
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', v):
                try:
                    v = datetime.date.fromisoformat(v)
                except ValueError:
                    pass
            elif re.fullmatch(r'-?\d+', v):
                v = int(v)
            fm[key] = v
    # An empty-value key followed by no list items stays as []; that's fine.

errs = []

for k in REQUIRED:
    if k not in fm:
        errs.append(f"missing required field: {k}")

if "owner_agent" in fm and str(fm["owner_agent"]).strip() not in VALID_AGENTS:
    errs.append(f"owner_agent must be one of {sorted(VALID_AGENTS)} (got: {fm['owner_agent']!r})")

if "state" in fm:
    s = str(fm["state"]).strip()
    if s and s not in {"active", "closed", "released"}:
        errs.append(f"state must be one of [active, closed, released] (got: {s!r})")

if "remaining_actions" in fm:
    ra = fm["remaining_actions"]
    if not isinstance(ra, list):
        errs.append("remaining_actions must be a list")

if "last_updated" in fm:
    try:
        d = fm["last_updated"]
        if isinstance(d, str):
            d = datetime.date.fromisoformat(d)
        age = (datetime.date.today() - d).days
        if age > MAX_AGE_DAYS:
            errs.append(f"last_updated is {age} days old (>{MAX_AGE_DAYS}d). Refresh it before handoff.")
    except (ValueError, TypeError):
        errs.append(f"last_updated not a valid ISO date: {fm.get('last_updated')!r}")

# Placeholder scan: no unfilled <...> token anywhere in the frontmatter block.
if re.search(r'<[^>]+>', block):
    errs.append("frontmatter contains an unfilled <...> placeholder; fill it before handoff.")

if errs:
    print(f"[handoff-check] {rel} frontmatter validation:", file=sys.stderr)
    for e in errs:
        print(f"  - {e}", file=sys.stderr)
else:
    print(f"[handoff-check] validated {rel} (ok)", file=sys.stderr)
PY
}

# ── Baton-lint (non-blocking) ────────────────────────────────────────────────
# Run scripts/notion_sync.py's lint_baton(slice) on the SAME slice(s) that
# validate_slice covers, and surface any issues under a [baton-lint] prefix.
#
# notion_sync computes REPO_ROOT from its own __file__ with NO env override, so
# a plain CLI invocation would read the REAL repo's .agent and ignore the
# AGENT_ROOT test seam. We therefore run the lint inline and monkeypatch
# notion_sync.REPO_ROOT to the PARENT of $AGENT_DIR (mirroring the pytest
# tests), so the hook honors AGENT_ROOT. Best-effort: any failure is silent and
# the hook's exit status is never affected.
lint_baton_warn() {
    # $1 = slice name (no .md). Prints a [baton-lint] block to stderr when the
    # lint reports issues; otherwise silent. Never changes the hook's exit code.
    local slice="$1"
    command -v python3 >/dev/null 2>&1 || return 0
    [ -f "$ROOT/scripts/notion_sync.py" ] || return 0
    local repo_for_lint
    repo_for_lint="$(cd "$AGENT_DIR/.." 2>/dev/null && pwd)" || return 0
    [ -n "$repo_for_lint" ] || return 0

    local out
    out="$(python3 - "$ROOT" "$repo_for_lint" "$slice" 2>/dev/null <<'PY' || true
import sys
sys.path.insert(0, sys.argv[1] + "/scripts")
from pathlib import Path
import notion_sync
notion_sync.REPO_ROOT = Path(sys.argv[2])
for issue in notion_sync.lint_baton(sys.argv[3]):
    print(issue)
PY
)"

    if [ -n "$out" ]; then
        {
            echo "[baton-lint] status/$slice.md:"
            printf '%s\n' "$out" | sed 's/^/  - /'
        } >&2
    fi
    return 0
}

# Read one frontmatter scalar from a status file (awk, no PyYAML needed).
fm_scalar() {
    awk -v key="$2" '
        /^---$/ { in_fm = !in_fm; next }
        in_fm {
            if (match($0, "^" key ":[[:space:]]*")) {
                v = substr($0, RLENGTH + 1)
                gsub(/^[[:space:]]*"|"[[:space:]]*$/, "", v)
                gsub(/^[[:space:]]+|[[:space:]]+$/, "", v)
                print v; exit
            }
        }
    ' "$1" 2>/dev/null
}

# Parse an ISO-8601 UTC timestamp to epoch seconds (GNU date -> python3).
iso_to_epoch() {
    date -u -d "$1" +%s 2>/dev/null \
        || python3 -c "import datetime,sys; print(int(datetime.datetime.strptime(sys.argv[1],'%Y-%m-%dT%H:%M:%SZ').replace(tzinfo=datetime.timezone.utc).timestamp()))" "$1" 2>/dev/null \
        || echo ""
}

if [ -n "${ENTERING_SLICE:-}" ]; then
    slice_file="$status_dir/$ENTERING_SLICE.md"
    if [ -f "$slice_file" ]; then
        validate_slice "$slice_file"
        lint_baton_warn "$ENTERING_SLICE"
    fi
    # If the named slice file is absent we stay silent — non-blocking by design.
elif [ -d "$status_dir" ]; then
    # No active slice named: validate every CLAIMED slice (non-empty
    # owner_session). This keeps the live single-session warning value without
    # depending on CURRENT.md's removed active_slice scalar.
    for slice_file in "$status_dir"/*.md; do
        [ -f "$slice_file" ] || continue
        # README.md documents the schema (its fenced example carries a sample
        # owner_session); it is not a slice. Skip it so the example never reads
        # as a live claim.
        [ "$(basename "$slice_file")" = "README.md" ] && continue
        owner="$(fm_scalar "$slice_file" owner_session)"
        [ -n "$owner" ] || continue
        validate_slice "$slice_file"
        lint_baton_warn "$(basename "$slice_file" .md)"
    done
fi

# ── Missed-handoff check (v0.4.1) ─────────────────────────────────────────────
# If the SessionStart hook wrote a session marker for this session_id, and any
# claimed slice's heartbeat predates the session start, warn — the session is
# ending without /handoff having been run for that slice.
session_id=""
if [ ! -t 0 ]; then
    # select with a tiny timeout so we never block waiting for EOF on a
    # connected-but-empty stdin (see session-start-decay-check.sh Job 1c).
    session_id=$(python3 -c 'import json, select, sys
if select.select([sys.stdin], [], [], 0.05)[0]:
    try:
        d = json.load(sys.stdin)
        print(d.get("session_id", ""))
    except Exception:
        pass' 2>/dev/null || echo "")
fi

if [ -n "$session_id" ]; then
    marker_file="$AGENT_DIR/handoffs/state/session-markers/$session_id.start"
    if [ -f "$marker_file" ]; then
        session_start=$(head -1 "$marker_file" 2>/dev/null | tr -d '[:space:]')
        if [ -n "$session_start" ] && [ -d "$status_dir" ]; then
            cur_sess="${OWNER_SESSION:-}"
            for sf in "$status_dir"/*.md; do
                [ -f "$sf" ] || continue
                [ "$(basename "$sf")" = "README.md" ] && continue
                s_owner=$(fm_scalar "$sf" owner_session)
                [ -n "$s_owner" ] || continue
                # If we know our own session, only warn for slices we own.
                # Otherwise warn for any claimed slice with heartbeat older than
                # session start (less precise, but still useful).
                if [ -n "$cur_sess" ] && [ "$s_owner" != "$cur_sess" ]; then
                    continue
                fi
                s_hb=$(fm_scalar "$sf" heartbeat)
                [ -n "$s_hb" ] || continue
                hb_epoch=$(iso_to_epoch "$s_hb")
                [ -n "$hb_epoch" ] || continue
                if [ "$hb_epoch" -lt "$session_start" ]; then
                    age_m=$(( (session_start - hb_epoch) / 60 ))
                    slice_name=$(basename "$sf" .md)
                    printf "[handoff-check] session ended without running handoff.sh for slice '%s' (heartbeat %dm before session start)\n" "$slice_name" "$age_m" >&2
                fi
            done
        fi
    fi
fi

# ── Home-staleness warning (non-blocking) ─────────────────────────────────────
# Task 7 writes .agent/handoffs/state/home-render.stamp on each successful
# Notion home apply (notion_sync.py --stamp-home-applied), recording the rev and
# an `applied: <ISO-UTC>` timestamp. The MCP write path is manual, so this hook
# can only REMIND: if any slice baton's mtime is newer than the last apply, the
# rendered Notion home is stale and should be refreshed. Advisory only — this
# section never changes the hook's exit status (the hook ends in `exit 0`).
stamp_file="$AGENT_DIR/handoffs/state/home-render.stamp"
if [ ! -f "$stamp_file" ]; then
    echo "[home-stale] no home-render.stamp — the Notion home has never been stamped; run ./scripts/notion_sync.py --render-home -> replace_content -> --stamp-home-applied" >&2
else
    # Value carries colons (HH:MM:SS), so capture everything after the first
    # "applied:" prefix rather than field-splitting on ':'.
    applied_iso=$(awk '/^applied:/ { sub(/^applied:[[:space:]]*/, ""); print; exit }' "$stamp_file" | tr -d '[:space:]')
    applied_epoch=$(iso_to_epoch "${applied_iso:-}")
    if [ -n "${applied_epoch:-}" ] && [ -d "$status_dir" ]; then
        stale_slices=""
        for sf in "$status_dir"/*.md; do
            [ -f "$sf" ] || continue
            [ "$(basename "$sf")" = "README.md" ] && continue
            m=$(file_mtime "$sf")
            [ -n "${m:-}" ] || continue
            if [ "$m" -gt "$applied_epoch" ]; then
                stale_slices="${stale_slices:+$stale_slices }$(basename "$sf" .md)"
            fi
        done
        if [ -n "$stale_slices" ]; then
            echo "[home-stale] baton(s) changed since the last home apply (${applied_iso}): ${stale_slices}. Run ./scripts/notion_sync.py --render-home -> MCP replace_content -> --stamp-home-applied to refresh the Notion home." >&2
        fi
    fi
fi

# ── Notion-sync-pending escalation (non-blocking) ─────────────────────────────
# A handoff that dropped a Notion sync writes a line per slice into
# .agent/handoffs/state/notion-sync-pending (the MCP replace_content step is
# manual and may not have run yet). This is an EXPLICIT, slice-named complement
# to the [home-stale] mtime backstop above: while [home-stale] infers staleness
# from mtimes, this marker records that a specific handoff deferred the write.
# Advisory only — this section never changes the hook's exit status.
notion_pending_marker="$AGENT_DIR/handoffs/state/notion-sync-pending"
if [ -s "$notion_pending_marker" ]; then
    pending_slices=$(awk '{print $1}' "$notion_pending_marker" 2>/dev/null | sort -u | paste -sd' ' - 2>/dev/null || true)
    echo "[notion-sync-pending] ${pending_slices} — a handoff dropped a Notion sync that has not been applied. Run ./scripts/notion_sync.py --emit-apply-plan <slice> -> MCP replace_content + update_properties (page_ids in the plan) -> --stamp-home-applied (clears it)." >&2
fi

# Project-hub re-sync (advisory): a slice handoff also flags its project hub.
notion_project_marker="$AGENT_DIR/handoffs/state/notion-project-pending"
if [ -s "$notion_project_marker" ]; then
    pending_projects=$(awk '{print $1}' "$notion_project_marker" 2>/dev/null | sort -u | paste -sd' ' - 2>/dev/null || true)
    echo "[notion-project-pending] ${pending_projects} — a project hub is stale. Run ./scripts/notion_sync.py --emit-project-plan <project> -> MCP replace_content (page_id in the plan) -> --stamp-project-applied <project> (clears it)." >&2
fi

exit 0
